#!/usr/bin/env python3
"""READ-ONLY privacy evidence for the unsigned iOS job (jc-privacy #32039). Writes markdown to $GITHUB_STEP_SUMMARY
(stdout if unset). Never edits a file, never fails the job (always exits 0): output is evidence, not a gate.
Part (a): every PrivacyInfo.xcprivacy in built products and resolved SwiftPM checkouts (path, sha256, declared types).
Part (b): file:line hits for the required-reason API families vs the app manifest's declared reasons."""
import glob, hashlib, os, plistlib, re, sys, traceback

MAX_LINES = 400
BEGIN = "=== IOS-PRIVACY-EVIDENCE BEGIN ==="
END = "=== IOS-PRIVACY-EVIDENCE END ==="


def main():

    HOME = os.path.expanduser("~")
    ROOT = os.environ.get("GITHUB_WORKSPACE", os.getcwd())
    DD = [os.environ.get("DERIVED_DATA", ""), os.path.join(HOME, "Library/Developer/Xcode/DerivedData")]
    APP_MANIFEST = os.path.join(ROOT, "mobile/ios/App/App/PrivacyInfo.xcprivacy")
    out = []
    def w(s=""): out.append(s)

    def find(roots, name):
        hits = []
        for r in roots:
            if r and os.path.isdir(r):
                for d, _, fs in os.walk(r):
                    if name in fs:
                        hits.append(os.path.join(d, name))
        return sorted(set(hits))

    def sha(p):
        return hashlib.sha256(open(p, "rb").read()).hexdigest()

    def parse(p):
        try:
            return plistlib.load(open(p, "rb"))
        except Exception as e:
            return {"_parse_error": str(e)}

    def describe(p):
        d = parse(p)
        if "_parse_error" in d:
            return "PARSE ERROR: " + d["_parse_error"]
        parts = ["NSPrivacyTracking=%s" % d.get("NSPrivacyTracking"),
                 "tracking domains=%s" % (d.get("NSPrivacyTrackingDomains") or [])]
        ct = [x.get("NSPrivacyCollectedDataType") for x in d.get("NSPrivacyCollectedDataTypes") or []]
        parts.append("collected=%s" % (ct or "none"))
        api = ["%s:%s" % (x.get("NSPrivacyAccessedAPIType", "?").replace("NSPrivacyAccessedAPICategory", ""),
                          ",".join(x.get("NSPrivacyAccessedAPITypeReasons") or []))
               for x in d.get("NSPrivacyAccessedAPITypes") or []]
        parts.append("accessed APIs=%s" % (api or "none"))
        return "; ".join(parts)

    def table(title, paths, base=None):
        w("### " + title)
        if not paths:
            w("_none found_")
        if len(paths) > 40:
            w("... %d more manifests not listed (cap 40 per section)" % (len(paths) - 40))
        for p in paths[:40]:
            w("- `%s`  sha256 `%s`" % (os.path.relpath(p, base) if base else p, sha(p)))
            w("  - " + describe(p))
        w()

    w("## READ-ONLY privacy evidence (jc-privacy #32039) - non-blocking, not a gate")
    w("Generated by .github/scripts/ios-privacy-evidence.py after the simulator compile. Nothing here edits a manifest.")
    w()
    w("### (a) PrivacyInfo.xcprivacy inventory")
    w()
    apps = []
    for r in DD:
        if r and os.path.isdir(r):
            apps += glob.glob(os.path.join(r, "**/Build/Products/*/*.app"), recursive=True)
    apps = sorted(set(apps))
    w("Built .app bundles found: %s" % (", ".join("`%s`" % a for a in apps) or "none (derived data not located)"))
    w()
    table("Inside the built simulator .app (incl. embedded frameworks)", sorted({m for a in apps for m in find([a], "PrivacyInfo.xcprivacy")}))
    checkouts = []
    for r in DD:
        if r and os.path.isdir(r):
            checkouts += glob.glob(os.path.join(r, "*/SourcePackages/checkouts"))
            checkouts += glob.glob(os.path.join(r, "SourcePackages/checkouts"))
    checkouts += glob.glob(os.path.join(ROOT, "mobile/ios/App/**/SourcePackages/checkouts"), recursive=True)
    table("SwiftPM resolved checkouts", [m for m in find(sorted(set(checkouts)), "PrivacyInfo.xcprivacy")])
    table("Source tree and node_modules (plugin packages)", [m for m in find([os.path.join(ROOT, "mobile/node_modules"), os.path.join(ROOT, "mobile/ios")], "PrivacyInfo.xcprivacy")], ROOT)

    FAMILIES = [
        ("UserDefaults", "NSPrivacyAccessedAPICategoryUserDefaults", "CA92.1", r"\b(NS)?UserDefaults\b"),
        ("File timestamp", "NSPrivacyAccessedAPICategoryFileTimestamp", "C617.1",
         r"\b(creationDate|modificationDate|fileModificationDate|fileCreationDate|NSFileCreationDate|NSFileModificationDate|"
         r"contentModificationDate|creationDateKey|contentModificationDateKey|contentAccessDateKey|f?l?stat|getattrlist|fgetattrlist|getattrlistbulk)\b"),
        ("System boot time", "NSPrivacyAccessedAPICategorySystemBootTime", "35F9.1",
         r"\b(systemUptime|mach_absolute_time|clock_gettime_nsec_np|kern\.boottime)\b"),
        ("Disk space", "NSPrivacyAccessedAPICategoryDiskSpace", "E174.1",
         r"\b(volumeAvailableCapacity\w*|volumeTotalCapacity\w*|NSFileSystemFreeSize|NSFileSystemSize|systemFreeSize|statfs|fstatfs|statvfs|fstatvfs)\b"),
        ("Active keyboards", "NSPrivacyAccessedAPICategoryActiveKeyboards", "54BD.1", r"\bactiveInputModes\b"),
    ]
    SRC = re.compile(r"\.(swift|m|mm|h|c|cpp)$")
    SKIP = re.compile(r"(^|/)(tests?|__tests__|\.build|Pods|xcuserdata)(/|$)|Tests?(/|$)", re.I)
    roots = [os.path.join(ROOT, "mobile/ios/App/App")]
    roots += glob.glob(os.path.join(ROOT, "mobile/node_modules/*/ios")) + glob.glob(os.path.join(ROOT, "mobile/node_modules/@*/*/ios"))
    roots += [c for c in sorted(set(checkouts)) if os.path.isdir(c)]
    hits = {f[0]: [] for f in FAMILIES}
    scanned = 0
    for r in roots:
        for d, _, fs in os.walk(r):
            if SKIP.search(os.path.relpath(d, r) + "/"):
                continue
            for f in fs:
                if not SRC.search(f):
                    continue
                p = os.path.join(d, f); scanned += 1
                try:
                    lines = open(p, encoding="utf-8", errors="replace").read().splitlines()
                except OSError:
                    continue
                for i, line in enumerate(lines, 1):
                    if line.lstrip().startswith("//"):
                        continue
                    for name, _, _, rx in FAMILIES:
                        if re.search(rx, line):
                            hits[name].append("%s:%d: %s" % (os.path.relpath(p, ROOT) if p.startswith(ROOT) else p, i, line.strip()[:110]))

    app = parse(APP_MANIFEST) if os.path.exists(APP_MANIFEST) else {}
    declared = {x.get("NSPrivacyAccessedAPIType"): x.get("NSPrivacyAccessedAPITypeReasons") or [] for x in app.get("NSPrivacyAccessedAPITypes") or []}
    w("### (b) Required-reason API usage vs the app manifest")
    w("Scanned %d native source files (app Swift/ObjC, plugin ios dirs under mobile/node_modules, SwiftPM checkouts; tests excluded). "
      "Regex line matches, comments skipped: a hit is a lead to read, not proof of a call." % scanned)
    w("Source roots: " + ", ".join("`%s`" % (os.path.relpath(r, ROOT) if r.startswith(ROOT) else r) for r in roots))
    w("App manifest declares: %s" % (", ".join("%s=%s" % (k.replace("NSPrivacyAccessedAPICategory", ""), "/".join(v)) for k, v in declared.items()) or "nothing"))
    w()
    for name, cat, reason, _ in FAMILIES:
        used = bool(hits[name]); decl = cat in declared
        status = "DECLARED" if used and decl else "NOT DECLARED but USED" if used else "UNUSED (declared anyway: %s)" % "/".join(declared[cat]) if decl else "UNUSED"
        w("#### %s (expected reason %s): %s%s" % (name, reason, status, " - %d hits" % len(hits[name]) if used else ""))
        for h in hits[name][:60]:
            w("- `%s`" % h)
        if len(hits[name]) > 60:
            w("- ... %d more" % (len(hits[name]) - 60))
        w()

    return "\n".join(out) + "\n"


def emit():
    try:
        text = main()
    except BaseException:
        text = "## READ-ONLY privacy evidence: SCRIPT EXCEPTION (non-blocking)\n```\n" + traceback.format_exc() + "```\n"
    lines = text.rstrip("\n").split("\n")
    if len(lines) > MAX_LINES:
        lines = lines[:MAX_LINES] + ["... %d more lines truncated (cap %d)" % (len(lines) - MAX_LINES, MAX_LINES)]
    text = "\n".join(lines) + "\n"
    print(BEGIN)
    sys.stdout.write(text)
    print(END)
    sys.stdout.flush()
    dest = os.environ.get("GITHUB_STEP_SUMMARY")
    if dest:
        try:
            open(dest, "a").write(text)
        except OSError as e:
            print("summary write failed: %s" % e)


emit()
